# Filter in-scope assays
# The manifest may either contain a top-level "assays" list or group assays under regions.
if 'assays' in manifest:
    manifest_assays = manifest['assays']
else:
    manifest_assays = []
    for region in manifest.get('regions', []):
        manifest_assays.extend(region.get('assays', []))

in_scope_assays = [a for a in manifest_assays if a.get('in_scope') == True]
